/* 外部删除屏幕时也清空引用，避免下次切屏使用悬空指针。 */
static void ui_launcher_deleted(lv_event_t * e)
{
    if (lv_event_get_target(e) != aidogui_ui.launcher.root) return;
    aidogui_ui.launcher.root = NULL;
}

